INSERT INTO feature VALUES('session-machine','sessions','Sessions run on the run''s scheduler','session-types','implemented','notable',NULL,'A fork, a send, a receive, a selection, an offer and a close run on one cooperative, deterministic scheduler the run holds, on its own thread and on both tiers. A channel keeps one queue per direction: a send or a selection never waits, and a receive or an offer with nothing sent parks its task''s frames until its peer sends. A fork''s parent runs on and its child joins the back of the ready queue; the run answers once every task has ended, and a run whose tasks all wait is stuck as a deadlock naming each waiting action. An end an abandoned continuation holds before its protocol ended is cancelled: the payloads queued at it are released, an end among them cancelled too, and a peer waiting on it is abandoned; a peer''s later send or selection, or a receive or an offer with nothing queued, abandons that peer''s continuation, its unwinds run and its own ends cancelled in turn, and a root so abandoned leaves the run stuck as cancelled at that action.','core-sequent runtime-emitter','corpus/model/sessions/seat-exchange.gandr corpus/model/sessions/dropped.gandr corpus/model/sessions/receive-payload.gandr corpus/model/moves/moved-through.gandr corpus/model/moves/moved-to-closer.gandr corpus/pathological/drop/cancelled-peer.gandr corpus/model/drop/cancelled-receiver.gandr crates/runtime-emitter/tests/sessions.rs','corpus/model/sessions/seat-exchange.gandr',NULL);
